using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ApplyCollisionProxies {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var meshes=new Dictionary<string,Mesh>();var models=JArray.Parse(File.ReadAllText(H+"collision_models.json"));foreach(var row in models){string p=(string)row["asset"];var mi=(ModelImporter)AssetImporter.GetAtPath(p);mi.importAnimation=false;mi.importLights=false;mi.importCameras=false;mi.materialImportMode=ModelImporterMaterialImportMode.None;mi.isReadable=true;mi.SaveAndReimport();meshes[(string)row["original"]]=AssetDatabase.LoadAllAssetsAtPath(p).OfType<Mesh>().Single();}var logs=new List<object>();var records=JArray.Parse(File.ReadAllText(H+"refined_colliders.json")).ToDictionary(j=>(string)j["id"]);try{foreach(string f in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Circular.unity");foreach(var t in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>())){string id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString();if(!records.TryGetValue(id,out var rec))continue;var boxes=t.GetComponents<BoxCollider>();var first=boxes[0];foreach(var b in boxes.Skip(1))UnityEngine.Object.DestroyImmediate(b);first.center=new Vector3((float)rec["oldCenter"][0],(float)rec["oldCenter"][1],(float)rec["oldCenter"][2]);first.size=new Vector3((float)rec["oldSize"][0],(float)rec["oldSize"][1],(float)rec["oldSize"][2]);first.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(first);var mc=t.GetComponent<MeshCollider>();if(!mc)mc=t.gameObject.AddComponent<MeshCollider>();mc.sharedMesh=meshes[(string)rec["asset"]];mc.convex=false;mc.isTrigger=false;mc.enabled=true;mc.sharedMaterial=first.sharedMaterial;PrefabUtility.RecordPrefabInstancePropertyModifications(mc);var rb=t.GetComponentInParent<Rigidbody>();if(rb&&!rb.isKinematic)throw new Exception("Dynamic body unsupported "+t.name);logs.Add(new{floor=f,name=t.name,asset=AssetDatabase.GetAssetPath(mc.sharedMesh),triangles=mc.sharedMesh.triangles.Length/3});}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(H+"proxies_applied.json",JsonConvert.SerializeObject(logs,Formatting.Indented));return new{models=meshes.Count,objects=logs.Count,totalUniqueTriangles=meshes.Values.Sum(m=>m.triangles.Length/3)};}
}
